// === PHOTO ===
const PHOTO_B64 = "";
document.getElementById('profile-photo').src = 'data:image/jpeg;base64,' + PHOTO_B64;

// === LOADER ===
window.addEventListener('load', () => {
  setTimeout(() => {
    document.getElementById('loader').classList.add('hide');
  }, 1600);
});

// === CURSOR ===
const cursor = document.getElementById('cursor');
const trail = document.getElementById('cursorTrail');
let mx = 0, my = 0, tx = 0, ty = 0;

document.addEventListener('mousemove', e => {
  mx = e.clientX;
  my = e.clientY;
  cursor.style.left = mx - 6 + 'px';
  cursor.style.top = my - 6 + 'px';
});

function animateTrail() {
  tx += (mx - tx) * 0.12;
  ty += (my - ty) * 0.12;
  trail.style.left = tx - 18 + 'px';
  trail.style.top = ty - 18 + 'px';
  requestAnimationFrame(animateTrail);
}
animateTrail();

// === PARTICLES ===
const pc = document.getElementById('particles');
for (let i = 0; i < 40; i++) {
  const p = document.createElement('div');
  p.className = 'particle';
  const s = Math.random() * 3 + 1;
  p.style.cssText = `width:${s}px;height:${s}px;left:${Math.random()*100}%;animation-duration:${Math.random()*15+8}s;animation-delay:${Math.random()*10}s;`;
  pc.appendChild(p);
}

// === TYPEWRITER ===
const phrases = [
  'Estudiante de Licenciatura en Sistemas y Programación',
  'Apasionado del Fútbol y la Tecnología',
  'Lector, Investigador y Soñador Digital',
  'Construyendo el Futuro desde Panamá'
];
let pi = 0, ci = 0, del = false;

function type() {
  const phrase = phrases[pi];
  const tw = document.getElementById('typewriter');
  if (!del) {
    tw.innerHTML = phrase.slice(0, ci + 1) + '<span class="type-cursor">|</span>';
    ci++;
    if (ci === phrase.length) { del = true; setTimeout(type, 2000); return; }
    setTimeout(type, 60);
  } else {
    tw.innerHTML = phrase.slice(0, ci) + '<span class="type-cursor">|</span>';
    ci--;
    if (ci === 0) { del = false; pi = (pi + 1) % phrases.length; setTimeout(type, 300); return; }
    setTimeout(type, 30);
  }
}
setTimeout(type, 1800);

// === NAVBAR SCROLL ===
window.addEventListener('scroll', () => {
  document.getElementById('navbar').classList.toggle('scrolled', window.scrollY > 50);
});

// === REVEAL ON SCROLL ===
const obs = new IntersectionObserver((entries) => {
  entries.forEach(e => {
    if (e.isIntersecting) e.target.classList.add('visible');
  });
}, { threshold: 0.1 });

document.querySelectorAll('.reveal, .timeline-item').forEach(el => obs.observe(el));

// === FORM SUBMIT ===
function handleSubmit(e) {
  e.preventDefault();
  const btn = e.target.querySelector('.form-submit');
  btn.textContent = '✓ ENVIADO';
  btn.style.background = 'linear-gradient(135deg, #00ff88, #00b8c4)';
  setTimeout(() => {
    btn.textContent = 'ENVIAR MENSAJE';
    btn.style.background = '';
    e.target.reset();
  }, 3000);
}

// === SMOOTH SCROLL ===
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    e.preventDefault();
    const t = document.querySelector(a.getAttribute('href'));
    if (t) t.scrollIntoView({ behavior: 'smooth' });
  });
});
